#include "save_slot_win32.hpp"
#include "message_dialog_win32.hpp"
#include "pc_window.hpp"
#include <iostream>
#include <stdexcept>
#include <vector>

namespace {
constexpr std::uint32_t up=0x10u,right=0x20u,down=0x40u,left=0x80u,circle=0x2000u,cross=0x4000u;
unsigned assertions{};
void require(bool okay,const char *why){++assertions;if(!okay)throw std::runtime_error(why);}
std::wstring desktop_name(HDESK desktop){DWORD size{};GetUserObjectInformationW(desktop,UOI_NAME,nullptr,0,&size);require(size!=0,"desktop name size");std::vector<wchar_t> text(size/sizeof(wchar_t));require(GetUserObjectInformationW(desktop,UOI_NAME,text.data(),size,&size)!=FALSE,"desktop name");return text.data();}
std::wstring input_desktop(){const auto desktop=OpenInputDesktop(0,FALSE,DESKTOP_READOBJECTS);require(desktop!=nullptr,"inspect input desktop");const auto name=desktop_name(desktop);CloseDesktop(desktop);return name;}
struct PrivateDesktop {
    HDESK original{},isolated{};std::wstring input_before;
    PrivateDesktop(){original=GetThreadDesktop(GetCurrentThreadId());require(original!=nullptr,"original thread desktop");input_before=input_desktop();const auto name=L"ChiliUtilityInputFixture_"+std::to_wstring(GetCurrentProcessId());isolated=CreateDesktopW(name.c_str(),nullptr,nullptr,0,DESKTOP_CREATEWINDOW|DESKTOP_CREATEMENU|DESKTOP_READOBJECTS|DESKTOP_WRITEOBJECTS|DESKTOP_HOOKCONTROL,nullptr);require(isolated!=nullptr,"create private desktop");if(!SetThreadDesktop(isolated)){CloseDesktop(isolated);isolated=nullptr;throw std::runtime_error("attach private desktop");}verify();}
    void verify(){require(GetThreadDesktop(GetCurrentThreadId())==isolated,"private desktop retained");require(input_desktop()==input_before,"user input desktop unchanged");}
    ~PrivateDesktop(){if(isolated){SetThreadDesktop(original);CloseDesktop(isolated);}}
};
HWND dialog(const wchar_t *expected){struct Search{const wchar_t *name;HWND window{};unsigned count{};}search{expected};EnumThreadWindows(GetCurrentThreadId(),[](HWND hwnd,LPARAM data)->BOOL{auto &s=*reinterpret_cast<Search*>(data);wchar_t name[128]{};GetClassNameW(hwnd,name,128);if(std::wstring(name)==s.name){s.window=hwnd;++s.count;}return TRUE;},reinterpret_cast<LPARAM>(&search));require(search.count<=1,"at most one presenter window");return search.window;}
HWND save_window(){return dialog(L"ChiliNativePspSaveSlotDialog");}
HWND message_window(){return dialog(L"ChiliNativePspMessageDialog");}
void hidden(HWND window,HWND parent){require(window&&IsWindow(window)&&!IsWindowVisible(window)&&!IsWindowVisible(parent),"fixture top-level windows hidden");require(!IsWindowEnabled(parent),"utility disables its game parent");}
void pump(chili::PcWindow &game){require(game.pump(),"hidden real PcWindow pump running");}
void key(HWND window,UINT code,bool pressed){require(PostMessageW(window,pressed?WM_KEYDOWN:WM_KEYUP,code,pressed?1:0xC0000001u)!=FALSE,"post private test key");}
void mouse(HWND button){require(button!=nullptr,"native button exists");require(PostMessageW(button,WM_LBUTTONDOWN,MK_LBUTTON,MAKELPARAM(8,8))!=FALSE&&PostMessageW(button,WM_LBUTTONUP,0,MAKELPARAM(8,8))!=FALSE,"post private test mouse");}
chili::SaveSlotRequest save_request(std::uint64_t generation,unsigned swap){chili::SaveSlotRequest r;r.generation=generation;r.title="Private focus fixture";r.language=1;r.button_swap=swap;for(unsigned i=0;i<3;++i)r.slots.push_back({"DATA0"+std::to_string(i),"Empty profile",false});return r;}
chili::MessageDialogRequest message_request(std::uint64_t generation,unsigned swap,bool yes_no=true,bool okay=false,bool back=true){chili::MessageDialogRequest r;r.generation=generation;r.size=708;r.mode=1;r.language=1;r.button_swap=swap;r.text="Private sampled-input fixture";r.yes_no=yes_no;r.okay=okay;r.allow_back=back;r.default_no=yes_no;r.suppress_sound=true;return r;}
template<class Presenter,class Choice>void selected(Presenter &presenter,std::uint64_t generation,Choice choice){const auto selection=presenter.poll(generation);require(selection&&selection->generation==generation&&selection->choice==choice,"expected one genuine choice");require(!presenter.poll(generation),"choice delivered once");}
void save_focus(){for(unsigned swap:{0u,1u}){
    chili::PcWindow game(false);const auto confirm=swap?cross:circle;std::optional<std::uint32_t> sample=confirm;chili::Win32SaveSlotPresenter presenter([&]{return game.handle();},false,[&]{return sample;});auto request=save_request(10+swap,swap);presenter.open(request);hidden(save_window(),game.handle());
    for(unsigned n=0;n<3;++n)require(!presenter.poll(request.generation),"held save confirm at open pending");
    sample.reset();require(!presenter.poll(request.generation),"inactive save sample pending");sample=confirm;for(unsigned n=0;n<3;++n)require(!presenter.poll(request.generation),"save resume with held confirm pending");
    sample=0;require(!presenter.poll(request.generation),"valid save release pending");sample=down;require(!presenter.poll(request.generation),"fresh down only navigates");require(SendMessageW(GetDlgItem(save_window(),100),LB_GETCURSEL,0,0)==1,"fresh down chooses actual DATA01 row");sample=0;presenter.poll(request.generation);sample=confirm;const auto choice=presenter.poll(request.generation);require(choice&&choice->choice==chili::SaveSlotChoice::Save&&choice->index==1,"release/new confirm selects actual empty DATA01");sample=0;require(!presenter.poll(request.generation),"completed save releases without new choice");sample=confirm;require(!presenter.poll(request.generation),"completed save cannot repeat after fresh edge");presenter.close(request.generation);require(IsWindowEnabled(game.handle()),"save teardown restores game owner");
    // An inactive source at open cannot convert a first held sample into input.
    sample.reset();++request.generation;presenter.open(request);sample=confirm;require(!presenter.poll(request.generation),"inactive-at-open first valid confirm baseline");sample=0;presenter.poll(request.generation);sample=swap?circle:cross;selected(presenter,request.generation,chili::SaveSlotChoice::Cancel);presenter.close(request.generation);
}
std::cout<<"PASS Save optional validity, both swaps, held open/resume, explicit release/new edge, choice once\n";}
void save_overwrite_focus(){chili::PcWindow game(false);std::optional<std::uint32_t> sample=0;chili::Win32SaveSlotPresenter presenter([&]{return game.handle();},false,[&]{return sample;});auto request=save_request(20,1);request.slots[0].exists=true;presenter.open(request);sample=cross;require(!presenter.poll(20),"existing Save only opens overwrite prompt");auto window=save_window();require(LOWORD(SendMessageW(window,DM_GETDEFID,0,0))==IDNO,"overwrite starts with Back default");sample=0;presenter.poll(20);sample=up;require(!presenter.poll(20)&&LOWORD(SendMessageW(window,DM_GETDEFID,0,0))==IDYES,"up chooses Overwrite without activation");sample.reset();require(!presenter.poll(20),"overwrite focus loss pending");sample=cross;for(unsigned n=0;n<3;++n)require(!presenter.poll(20),"held confirm on overwrite resume pending");sample=0;presenter.poll(20);sample=cross;selected(presenter,20,chili::SaveSlotChoice::Save);presenter.close(20);std::cout<<"PASS Overwrite held confirm on resume requires fresh release/edge\n";}
void message_focus(){for(unsigned swap:{0u,1u}){
    chili::PcWindow game(false);const auto confirm=swap?cross:circle,back=swap?circle:cross;std::optional<std::uint32_t> sample=confirm;chili::Win32MessageDialogPresenter presenter([&]{return game.handle();},false,[&]{return sample;});auto request=message_request(30+swap,swap);presenter.open(request);hidden(message_window(),game.handle());
    for(unsigned n=0;n<3;++n)require(!presenter.poll(request.generation),"held message confirm at open pending");sample.reset();require(!presenter.poll(request.generation),"inactive message sample pending");sample=confirm;for(unsigned n=0;n<3;++n)require(!presenter.poll(request.generation),"message resume held confirm pending");sample=0;require(!presenter.poll(request.generation),"message valid release pending");sample=confirm;selected(presenter,request.generation,chili::MessageDialogChoice::No);sample=0;presenter.poll(request.generation);sample=back;require(!presenter.poll(request.generation),"completed message cannot emit second choice");presenter.close(request.generation);
    sample.reset();++request.generation;presenter.open(request);sample=left;require(!presenter.poll(request.generation)&&LOWORD(SendMessageW(message_window(),DM_GETDEFID,0,0))==IDNO,"resume-held navigation baselined");sample=0;presenter.poll(request.generation);sample=left;require(!presenter.poll(request.generation)&&LOWORD(SendMessageW(message_window(),DM_GETDEFID,0,0))==IDYES,"left edge moves default No to Yes");sample=0;presenter.poll(request.generation);sample=confirm;selected(presenter,request.generation,chili::MessageDialogChoice::Yes);presenter.close(request.generation);
    sample=0;++request.generation;presenter.open(request);sample=back;selected(presenter,request.generation,chili::MessageDialogChoice::Back);presenter.close(request.generation);
}
std::cout<<"PASS Message gamepad both swaps, held open/resume, default No/Yes navigation, Back and choice once\n";}
void message_constraints(){chili::PcWindow game(false);std::optional<std::uint32_t> sample=0;chili::Win32MessageDialogPresenter presenter([&]{return game.handle();},false,[&]{return sample;});auto request=message_request(40,1,false,true,false);presenter.open(request);require(GetDlgItem(message_window(),IDCANCEL)==nullptr,"no-cancel has no Back control");sample=circle;require(!presenter.poll(40),"disallowed PSP Back stays pending");sample=0;presenter.poll(40);sample=right;require(!presenter.poll(40)&&LOWORD(SendMessageW(message_window(),DM_GETDEFID,0,0))==IDOK,"navigation constrained to existing Okay");sample=0;presenter.poll(40);sample=cross;selected(presenter,40,chili::MessageDialogChoice::Okay);presenter.close(40);
    sample=0;request=message_request(41,1,false,false,true);presenter.open(request);sample=cross;selected(presenter,41,chili::MessageDialogChoice::Back);presenter.close(41);
    sample=0;request=message_request(42,1);presenter.open(request);sample=left|right;require(!presenter.poll(42)&&LOWORD(SendMessageW(message_window(),DM_GETDEFID,0,0))==IDNO,"opposing navigation leaves default unchanged");sample=0;presenter.poll(42);sample=cross|circle;selected(presenter,42,chili::MessageDialogChoice::Back);presenter.close(42);std::cout<<"PASS Message available-choice bounds, no-cancel, Back-only, opposing directions and Back precedence\n";}
void native_paths(){chili::PcWindow game(false);std::optional<std::uint32_t> sample;{
    chili::Win32SaveSlotPresenter presenter([&]{return game.handle();},false,[&]{return sample;});presenter.open(save_request(50,1));const auto list=GetDlgItem(save_window(),100);SetFocus(list);key(list,VK_RETURN,true);key(list,VK_RETURN,false);pump(game);selected(presenter,50,chili::SaveSlotChoice::Save);presenter.close(50);
}{chili::Win32MessageDialogPresenter presenter([&]{return game.handle();},false,[&]{return sample;});presenter.open(message_request(51,1));const auto no=GetDlgItem(message_window(),IDNO);SetFocus(no);key(no,VK_RETURN,true);key(no,VK_RETURN,false);pump(game);selected(presenter,51,chili::MessageDialogChoice::No);presenter.close(51);
    presenter.open(message_request(52,1));mouse(GetDlgItem(message_window(),IDYES));pump(game);selected(presenter,52,chili::MessageDialogChoice::Yes);presenter.close(52);}
    // The port's ordinary combined sampler reports Space as Cross. A native
    // Space down on Back must not also activate the current PSP default No.
    sample=0;chili::Win32MessageDialogPresenter presenter([&]{return game.handle();},false,[&]{return sample;});presenter.open(message_request(53,1));const auto back=GetDlgItem(message_window(),IDCANCEL);SetFocus(back);sample=cross;key(back,VK_SPACE,true);pump(game);require(!presenter.poll(53),"native Space down suppresses combined Cross default activation");sample=0;key(back,VK_SPACE,false);pump(game);selected(presenter,53,chili::MessageDialogChoice::Back);presenter.close(53);
    std::cout<<"PASS Inactive sampled source preserves native Enter/mouse; combined Space does not misconfirm\n";
}
}
int main(){try{PrivateDesktop desktop;save_focus();desktop.verify();save_overwrite_focus();desktop.verify();message_focus();desktop.verify();message_constraints();desktop.verify();native_paths();desktop.verify();require(!save_window()&&!message_window(),"no presenter windows remain");std::cout<<"Utility input fixture PASS: "<<assertions<<" assertions; hidden windows/private desktop only; no OS input or game launch\n";return 0;}catch(const std::exception &error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}}
